import{z as p,x as A,o as n,c as d,q as s,j as r,D as l,d as t,s as i,S as E,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"字母表、串与语言","description":"","frontmatter":{"title":"字母表、串与语言","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/alphabet-language.md","filePath":"cs/alphabet-language.md","lastUpdated":1791063341000}'),m={name:"cs/alphabet-language.md"};function B(g,a,h,u,c,b){const o=A("Mermaid");return n(),d("div",null,[a[2]||(a[2]=s('<h1 id="字母表、串与语言" tabindex="-1">字母表、串与语言 <a class="header-anchor" href="#字母表、串与语言" aria-label="Permalink to &quot;字母表、串与语言&quot;">​</a></h1><div class="epigraph"><p>计算理论的第一批对象不是门和进程，而是有限符号、有限串，以及串的集合；语言是集合，不是自然语言。</p><footer>—— 据 Hopcroft, Motwani and Ullman, Introduction to Automata Theory；Sipser, Introduction to the Theory of Computation 整理</footer></div><p>主干在<a href="/cs/to-systems-boundary">系统边界</a>封口：从比特到隔离与会话，可执行的系统栈已经闭合。本课是补层「计算理论」第一课，不重开组成、不重讲操作系统。缺口是另一类问题——<strong>哪些串集合能被机器认、判定、计数</strong>——要从字母表写起。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/cs/bit-as-distinction">比特作为区分</a>把世界切成 \\(\\{0,1\\}\\)；那是编码层的最小字母表，不是本课的起点。理论课允许任意有限非空 \\(\\Sigma\\)（记号、自然数的十进制数字、栈符号），\\(0/1\\) 只是其中一个特例。对比：比特问「两种状态如何编号」；字母表问「符号一旦给定，串与语言怎么写」。不要把本课写成第一课的续篇。</p><p>字母表 \\(\\Sigma\\) 有限。串是 \\(\\Sigma\\) 上的有限序列，含空串 \\(\\varepsilon\\)。\\(\\Sigma^*\\) 是全体串。语言 \\(L\\subseteq\\Sigma^*\\)。运算：连接 \\(LL&#39;\\)、并、Kleene 星 \\(L^*\\)。后课自动机认的是语言，不是「一个程序在干什么」。</p><p><span class="marginnote">术语翻译：Kleene 星 \\(L^*\\) 读作「L 的星闭包」——把 \\(L\\) 里的串任意取、任意拼接、重复任意多次（包括零次）得到的全部结果。例如 \\(L=\\{ab\\}\\)，则 \\(L^*=\\{\\varepsilon, ab, abab, ababab,\\ldots\\}\\)：有限的语言经一颗星就闭合成无穷集。</span></p><h3 id="语言不是语法-也不是语义" tabindex="-1">语言不是语法，也不是语义 <a class="header-anchor" href="#语言不是语法-也不是语义" aria-label="Permalink to &quot;语言不是语法，也不是语义&quot;">​</a></h3><p>日常把 language 当成自然语言或编程语言。这里 \\(L\\) 只是串集：可以不可判定、可以没有文法、可以没有「意思」。CFG、类型、真值都是后课往这个集合上加的结构。本课只钉集合本身。</p><p><span class="marginnote">Hopcroft–Ullman 与 Sipser 都以 \\(\\Sigma,w,L\\) 开篇。Chomsky 把语言当生成对象；本课先当集合，下一课才分层。空语言 \\(\\emptyset\\) 与 \\(\\{\\varepsilon\\}\\) 不同：一个没有串，一个只有空串。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>约定：\\(\\Sigma\\) 有限且事先固定；后课换字母表会显式声明。串长 \\(|w|\\)，连接可结合，\\(\\varepsilon\\) 是单位元。语言的并、交、补相对 \\(\\Sigma^*\\)。可数性：\\(\\Sigma^*\\) 可数（按长、再按字典序），其幂集不可数——后课对角化要用这一句，本课只登记。</p><p><span class="marginnote">常见误区：初学者容易把空串 \\(\\varepsilon\\)、空语言 \\(\\emptyset\\)、语言 \\(\\{\\varepsilon\\}\\) 混为一谈。\\(\\varepsilon\\) 是零长的串（像乘法里的 1）；\\(\\emptyset\\) 一个串都没有；\\(\\{\\varepsilon\\}\\) 恰有一个串。验算一下：\\(L\\cdot\\{\\varepsilon\\}=L\\)，而 \\(L\\cdot\\emptyset=\\emptyset\\)——三者行为完全不同。</span></p>',13)),(n(),r(E,null,{default:l(()=>[i(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20SIG%5B%22%E6%9C%89%E9%99%90%E5%AD%97%E6%AF%8D%E8%A1%A8%20%CE%A3%22%5D%20--%3E%20STR%5B%22%E4%B8%B2%20%CE%A3*%22%5D%0A%20%20STR%20--%3E%20LANG%5B%22%E8%AF%AD%E8%A8%80%20L%20%E2%8A%86%20%CE%A3*%22%5D%0A%20%20LANG%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E6%96%87%E6%B3%95%E4%B8%8E%E6%9C%BA%E5%99%A8%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[t("主干"),e("a",{href:"/cs/regex-lexer"},"词法"),t("已经把记号种别当成正则语言用过；那里 \\(\\Sigma\\) 是源字符。本课把同一写法收成理论原语，不再谈最长匹配。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"有了 \\(L\\)，才能问：有没有有限描述（正则、文法、图灵机）生成或识别它。描述是对象，语言是外延。两个不同文法可以同语言。后课等价、最小化、不可判定，比的都是外延或「是否存在某类描述」，不是程序文本是否相同。",-1)),a[6]||(a[6]=e("p",null,"「外延相同就是同一语言」是什么意思？三种长得完全不一样的描述，指的可以是同一个串集合：",-1)),(n(),r(E,null,{default:l(()=>[i(o,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E6%AD%A3%E5%88%99%E5%BC%8F%20a%EF%BC%88b%EF%BD%9Cc%EF%BC%89*%22%5D%20--%3E%20L%5B%22%E5%90%8C%E4%B8%80%E4%B8%AA%E8%AF%AD%E8%A8%80%EF%BC%9Aa%20%E5%BC%80%E5%A4%B4%E3%80%81%E5%90%8E%E9%9D%A2%E6%8E%A5%E4%BB%BB%E6%84%8F%E4%B8%AA%20b%20%E6%88%96%20c%20%E7%9A%84%E5%85%A8%E4%BD%93%E4%B8%B2%22%5D%0A%20%20G%5B%22%E6%96%87%E6%B3%95%20S%E2%86%92aT%EF%BC%8CT%E2%86%92bT%EF%BD%9CcT%EF%BD%9C%CE%B5%22%5D%20--%3E%20L%0A%20%20M%5B%22%E6%9F%90%E4%B8%AA%20DFA%20%E7%9A%84%E6%8E%A5%E5%8F%97%E9%9B%86%22%5D%20--%3E%20L%0A%20%20L%20--%3E%20EQ%5B%22%E5%A4%96%E5%BB%B6%E7%9B%B8%E5%90%8C%20%E2%87%92%20%E5%90%8E%E8%AF%BE%E6%8A%8A%E5%AE%83%E4%BB%AC%E5%BD%93%E6%88%90%E5%90%8C%E4%B8%80%E5%AF%B9%E8%B1%A1%E6%9D%A5%E6%9C%80%E5%B0%8F%E5%8C%96%E3%80%81%E5%88%A4%E7%AD%89%E4%BB%B7%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<p><span class="marginnote">为什么重要：\\(\\Sigma^*\\) 可数，但它的幂集（全体语言）不可数，而文法、自动机这类有限描述至多可数多个。两数一相减就得出：<strong>绝大多数语言没有任何有限描述</strong>。这不是技术困难，是数出来的鸿沟——后面不可判定性、对角化全是这条裂缝的具体化。</span></p><p>编码：任何有限对象可写成 \\(\\Sigma=\\{0,1\\}\\) 上的串。补层后半的图灵机、归约，默认问题已经是语言。这与系统栈里「文件是字节」同一层习惯，对象换成判定问题。</p><p>连接与星把有限描述闭成无穷语言，但描述本身仍有限：后课谈的「正则式」「文法」「图灵机」都是有限对象去指称可能无穷的 \\(L\\)。\\(\\Sigma^*\\) 可数保证后课可以把问题枚举成 \\(\\langle 0\\rangle,\\langle 1\\rangle,\\ldots\\)；幂集不可数保证「大多数语言没有有限描述」——对角化课会用，此处只占坑。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不定义自动机，不引入产生式，不把 \\(\\{0,1\\}^*\\) 上的可计算函数写出来。不从 Turing 1936 重讲「什么是计算」——那是本课程后半的缺口。也不把 Shannon 熵请来：符号可以没有概率。</p><p>后课默认：谈到语言，即 \\(\\Sigma^*\\) 的子集；谈到问题，即把实例编成串之后的语言。Chomsky 层级是下一课把描述能力分层。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>补层从字母表、串、语言起；主干系统栈已在边界封口。</li><li>\\(L\\subseteq\\Sigma^*\\) 是集合；空语言与 \\(\\{\\varepsilon\\}\\) 不同。</li><li>比特字母表只是对照，不是本课的生成定义。</li><li>出处：Hopcroft, Motwani and Ullman；Sipser。</li></ul>',8))])}const f=p(m,[["render",B]]);export{S as __pageData,f as default};
